def closest_numbers(arr: list[int]) -> list[int]:
    best = float('inf')
    pairs: list[tuple[int, int]] = []
    n = len(arr)
    for i in range(n):
        for j in range(i + 1, n):
            diff = abs(arr[i] - arr[j])
            lo, hi = min(arr[i], arr[j]), max(arr[i], arr[j])
            if diff < best:
                best = diff
                pairs = [(lo, hi)]
            elif diff == best:
                pairs.append((lo, hi))
    pairs.sort()
    out: list[int] = []
    for lo, hi in pairs:
        out += [lo, hi]
    return out

