public List<Integer> closestNumbers(int[] arr) {
    Arrays.sort(arr);
    int minGap = Integer.MAX_VALUE;
    for (int i = 0; i + 1 < arr.length; i++) {
        minGap = Math.min(minGap, arr[i + 1] - arr[i]);
    }
    List<Integer> out = new ArrayList<>();
    for (int i = 0; i + 1 < arr.length; i++) {
        if (arr[i + 1] - arr[i] == minGap) {
            out.add(arr[i]);
            out.add(arr[i + 1]);
        }
    }
    return out;
}

